import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';

function isValidDate(dateString) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateString);
  if (!match) return false;
  const [, year, month, day] = match;
  const date = new Date(`${year}-${month}-${day}T00:00:00Z`);
  if (Number.isNaN(date.getTime())) return false;
  return date.toISOString().startsWith(`${year}-${month}-${day}`);
}

export function createInvoice({ customerId, issueDate, lines }) {
  const customer = getCustomer(customerId);
  if (!customer.ok) return customer;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!lines || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (typeof line.qty !== 'number' || !Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const product = getProduct(line.sku);
    if (!product.ok) return product;

    invoiceLines.push({
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

export function invoiceTotals(invoice) {
  const subtotal = roundCents(invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));
  return {
    subtotal,
    total: subtotal,
  };
}

export function addLine(invoice, { sku, qty }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (typeof qty !== 'number' || !Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const product = getProduct(sku);
  if (!product.ok) return product;

  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
  } else {
    newLines.push({
      sku,
      name: product.value.name,
      qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineExists = invoice.lines.some((line) => line.sku === sku);
  if (!lineExists) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

